    wares: [['Cambio suelas, tacones y cierres, y pongo plantillas. También lustro.', 'I replace soles, heels and zips, and fit insoles. I also polish.'], ['El cuero se cuida con betún y paciencia, no con cualquier crema.', 'Leather is cared for with polish and patience, not with just any cream.'], ['Con la humedad de la ladera las suelas se despegan rápido. Yo las dejo firmes.', 'With the hillside damp, soles come unstuck quickly. I leave them firm.']],
    news: [['Los zapatos del colegio llegan todos rotos en febrero. Es mi temporada.', 'School shoes all arrive broken in February. That is my season.'], ['Dicen que abre una tienda de zapatos baratos en el centro. Ojalá no se lleve a mis clientes.', 'They say a cheap shoe shop is opening downtown. Hopefully it does not take my clients.']],
    family: [['Mi hijo no quiso seguir el oficio, pero me ayuda con las cuentas.', 'My son did not want to follow the trade, but he helps me with the accounts.']],
    barrio: [['Este cerro es de subir y bajar escalinatas todo el día. Por eso aquí los zapatos se gastan rápido.', 'This hill is all climbing and descending stairways. That is why shoes wear out fast here.']],
    tip: [['Con tanta escalera, lleve zapatos cómodos. Y si se le dañan, ya sabe dónde estoy.', 'With so many stairs, wear comfortable shoes. And if they break, you know where I am.']],
    bye: [['Que le dure el calzado. ¡Hasta luego!', 'May your shoes last. See you later!'], ['Vuelva cuando se le gaste una suela.', 'Come back when a sole wears out.']],
    buy_ask: [['Claro. ¿Qué le arreglo?', 'Of course. What shall I mend for you?']],
